authority:
requireAdminRequest | validateBrandId | tutorialDb
      .select()
      .from(tutorialSidebarTreesV2)
      .where(and(
        eq(tutorialSidebarTreesV2.brandId, brandId),
        eq(tutorialSidebarTreesV2.topicId, topicId)
      ))
      .limit | authenticateRequest | createAuthErrorResponse | requireBrandAccess | requireSubtopicAccess | tx
              .insert(tutorialSidebarTreesV2)
              .values(values)
              .onConflictDoUpdate({
                target: [
                  tutorialSidebarTreesV2.brandId,
                  tutorialSidebarTreesV2.topicId,
                ],
                set: {
                  ...values,
                  version: sql`${tutorialSidebarTreesV2.version} + 1`,
                },
              })
              .returning | tx
          .insert(tutorialSidebarTreesV2)
          .values(values)
          .onConflictDoUpdate({
            target: [
              tutorialSidebarTreesV2.brandId,
              tutorialSidebarTreesV2.topicId,
            ],
            set: {
              ...values,
              version: sql`${tutorialSidebarTreesV2.version} + 1`,
            },
          })
          .returning

